"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["82690"],{66704(e){e.exports=JSON.parse('{"id":"FIN-1420","slug":"cyber-insurance","term":"Cyber Insurance","also_known_as":[],"difficulty":"Advanced","definition":"Cyber insurance is insurance that covers financial losses resulting from cyber incidents, such as data breaches, ransomware attacks, hacking and system failures.","explanation":["As cyber risk has grown, cyber insurance has become an important way for organisations to transfer part of its financial impact. Policies vary widely, but typically cover two types of loss.","First-party cover pays the insured organisation\'s own costs, such as investigating and responding to an incident, restoring data and systems, notifying affected customers, lost income from business interruption and, in some cases, ransom payments where legal. Third-party cover pays for claims from others, such as customers whose data was stolen, and regulatory fines and penalties where insurable.","For example, after a data breach exposing customer records, a retailer\'s cyber policy might pay for forensic experts, legal advice, customer notifications, credit monitoring services and settlements with affected customers.","Insurers increasingly require minimum security standards, such as multi-factor authentication and regular backups, before offering cover. The market has faced challenges, including rising ransomware claims, difficulty modelling risk and the potential for one widespread attack to affect many policyholders at once. Exclusions, such as for acts of war, can be significant."],"note":"","total":1500,"prev":{"slug":"customer-retention","term":"Customer Retention"},"next":{"slug":"cyber-risk","term":"Cyber Risk"}}')}}]);